// @ts-nocheck
import { useEffect, useState, type ReactNode } from 'react'
// The legacy employee panel remains in this module for backwards-compatible builds; the rendered panel is standalone personnel management.
import { BarChart3, Bike, CheckCircle2, ClipboardList, Clock3, History, MapPin, PackageCheck, Plus, RefreshCw, Truck, UserRoundX, Users, XCircle, type LucideIcon } from 'lucide-react'
import { api } from '../lib/api'
import { EmptyState, ErrorState, LoadingState, PageHeader, StatusBadge, useConfirmation } from '../components/ui'

type Page<T> = { data: T[]; current_page: number; last_page: number; total: number; per_page: number }
type Branch = { id: string; name: string; code?: string }
type EmployeeOption = { id: string; employee_number: string; name: string; email?: string | null; phone?: string | null; job_role?: string | null; department?: string | null; photo_available?: boolean; branches?: Array<{ id: string; name: string; role?: string }> }
type Partner = { id: string; name: string; phone?: string | null; email?: string | null; status?: string }
type Staff = { id: string; staff_code: string; name?: string; full_name?: string | null; phone?: string | null; email?: string | null; emergency_contact?: string | null; employment_type?: string | null; notes?: string | null; max_active_assignments?: number; workload?: number; branches?: Array<{ id: string; name: string }>; status: string; availability_status: string; vehicle_type?: string | null; vehicle_plate?: string | null; delivery_role?: string | null; assignment_eligibility?: boolean; approval_status?: string | null; store?: { id: string; name: string } | null; employee?: { id?: string; name?: string; email?: string | null; phone?: string | null; emergency_contact?: string | null } | null }
type Order = { id: string; vendor_order_number: string; order_number?: string | null; customer_name?: string | null; delivery_address?: Record<string, unknown> | string | null; total?: string | number | null; currency_code?: string | null; status: string; created_at?: string | null; store?: { id: string; name: string } | null }
type Shipment = { id: string; status: string; assignment_status: string; delivery_type: string; delivery_date?: string | null; assigned_at?: string | null; internal_tracking_id?: string | null; tracking_number?: string | null; carrier_name?: string | null; delivery_notes?: string | null; created_at?: string | null; shipped_at?: string | null; delivered_at?: string | null; branch?: { id: string; name: string; code?: string } | null; branches?: Array<{ id: string; name: string; code?: string }>; order?: Order | null; staff?: { id: string; name: string; staff_code: string; vehicle_type?: string | null; vehicle_plate?: string | null; availability_status?: string; status?: string; active_assignments?: number; max_active_assignments?: number } | null; courier_partner?: { id: string; name: string } | null; events?: Array<{ id: number; type: string; reason?: string | null; notes?: string | null; event_time?: string | null; actor_name?: string | null }> }
type Dashboard = { staff: { total: number; available: number; busy: number; off_duty: number }; deliveries: { pending_assignment: number; active: number; delivered_today: number; failed: number }; eligible_orders: number }
type Lookup = { employees: EmployeeOption[]; stores: Branch[]; partners: Partner[] }
type Report = { summary: { total: number; delivered: number; failed: number; active: number }; staff: Array<{ id: string; name: string; delivered: number; failed: number; total: number }> }
type Tab = 'dashboard' | 'staff' | 'assign' | 'active' | 'history' | 'couriers' | 'reports'

const inputClass = 'mt-1 w-full rounded-[10px] border border-slate-300 bg-white px-3 py-2.5 text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100 dark:focus:border-blue-400 dark:focus:ring-blue-950'
const tabs: Array<{ id: Tab; label: string; icon: typeof Truck }> = [
  { id: 'dashboard', label: 'Dashboard', icon: BarChart3 }, { id: 'staff', label: 'Delivery staff', icon: Users }, { id: 'assign', label: 'Assign delivery', icon: ClipboardList }, { id: 'active', label: 'Active deliveries', icon: Truck }, { id: 'history', label: 'Delivery history', icon: History }, { id: 'couriers', label: 'Courier partners', icon: Bike }, { id: 'reports', label: 'Reports', icon: BarChart3 },
]

function message(error: unknown, fallback: string): string {
  const value = error as { response?: { data?: { message?: string; errors?: Record<string, string[]> } } }
  return value?.response?.data?.message || Object.values(value?.response?.data?.errors || {})[0]?.[0] || fallback
}

export function DeliveryManagementPage() {
  const { requestConfirmation } = useConfirmation()
  const [tab, setTab] = useState<Tab>('dashboard')
  const [dashboard, setDashboard] = useState<Dashboard | null>(null)
  const [lookup, setLookup] = useState<Lookup>({ employees: [], stores: [], partners: [] })
  const [staff, setStaff] = useState<Page<Staff> | null>(null)
  const [orders, setOrders] = useState<Page<Order> | null>(null)
  const [assignableShipments, setAssignableShipments] = useState<Page<Shipment> | null>(null)
  const [shipmentStatusFilter, setShipmentStatusFilter] = useState('')
  const [shipmentBranchFilter, setShipmentBranchFilter] = useState('')
  const [active, setActive] = useState<Page<Shipment> | null>(null)
  const [history, setHistory] = useState<Page<Shipment> | null>(null)
  const [report, setReport] = useState<Report | null>(null)
  const [partners, setPartners] = useState<Partner[]>([])
  const [search, setSearch] = useState('')
  const [perPage, setPerPage] = useState(20)
  const [page, setPage] = useState(1)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [showStaffForm, setShowStaffForm] = useState(false)
  const [editingStaff, setEditingStaff] = useState<Staff | null>(null)
  const [staffForm, setStaffForm] = useState({ employee_profile_id: '', store_id: '', staff_code: '', vehicle_type: '', vehicle_plate: '', delivery_role: 'delivery_staff', assignment_eligibility: true, approval_status: 'approved' })
  const [assignForm, setAssignForm] = useState({ order_id: '', delivery_type: 'self_delivery', staff_id: '', courier_partner_id: '', delivery_date: '', delivery_instructions: '' })
  const [courierForm, setCourierForm] = useState({ name: '', phone: '', email: '', notes: '' })
  const [editingPartner, setEditingPartner] = useState<Partner | null>(null)
  const [reassignFor, setReassignFor] = useState<string | null>(null)
  const [reassignStaff, setReassignStaff] = useState('')
  const [reassignReason, setReassignReason] = useState('Operational reassignment')
  const [proofFiles, setProofFiles] = useState<Record<string, File | undefined>>({})
  const initialTab: Tab = window.location.pathname.endsWith('/assign') ? 'assign' : 'dashboard'
  useEffect(() => { setTab(initialTab) }, [])

  const loadLookup = async () => {
    const response = await api.get<{ data: Lookup }>('/api/v1/business/delivery-management/lookup')
    setLookup(response.data.data); setPartners(response.data.data.partners)
  }
  const loadDashboard = async () => { const response = await api.get<{ data: Dashboard }>('/api/v1/business/delivery-management/dashboard'); setDashboard(response.data.data) }
  const loadStaff = async () => { const response = await api.get<{ data: Page<Staff> }>('/api/v1/business/delivery-management/staff', { params: { search: search || undefined, page, per_page: perPage } }); setStaff(response.data.data) }
  const loadOrders = async () => { const response = await api.get<{ data: Page<Order> }>('/api/v1/business/delivery-management/orders/eligible', { params: { search: search || undefined, page, per_page: perPage } }); setOrders(response.data.data) }
  const loadAssignableShipments = async () => { const response = await api.get<{ data: Page<Shipment> }>('/api/v1/business/delivery-management/shipments/assignable', { params: { search: search || undefined, status: shipmentStatusFilter || undefined, store_id: shipmentBranchFilter || undefined, page, per_page: perPage } }); setAssignableShipments(response.data.data) }
  const loadShipments = async (kind: 'active' | 'history') => { const response = await api.get<{ data: Page<Shipment> }>(`/api/v1/business/delivery-management/${kind}`, { params: { search: search || undefined, page, per_page: perPage } }); if (kind === 'active') setActive(response.data.data); else setHistory(response.data.data) }
  const loadReports = async () => { const response = await api.get<{ data: Report }>('/api/v1/business/delivery-management/reports'); setReport(response.data.data) }
  const loadAll = async () => {
    setLoading(true); setError('')
    try { await Promise.all([loadDashboard(), loadLookup(), loadStaff(), loadOrders(), loadAssignableShipments(), loadShipments('active'), loadShipments('history'), loadReports()]) } catch (err) { setError(message(err, 'Unable to load delivery management data.')) } finally { setLoading(false) }
  }
  useEffect(() => { void loadAll() }, [])
  useEffect(() => { if (!loading) { if (tab === 'staff') void loadStaff().catch((err) => setError(message(err, 'Unable to load delivery staff.'))); if (tab === 'assign') void loadAssignableShipments().catch((err) => setError(message(err, 'Unable to load assignable shipments.'))); if (tab === 'active') void loadShipments('active').catch((err) => setError(message(err, 'Unable to load active deliveries.'))); if (tab === 'history') void loadShipments('history').catch((err) => setError(message(err, 'Unable to load delivery history.'))) } }, [tab, page, perPage, search, shipmentStatusFilter, shipmentBranchFilter])

  const refresh = async () => { setNotice(''); await loadAll() }
  const run = async (action: () => Promise<void>, success: string) => { setSaving(true); setError(''); setNotice(''); try { await action(); setNotice(success); await loadAll() } catch (err) { setError(message(err, 'Unable to complete the delivery action.')) } finally { setSaving(false) } }
  const confirmAssign = () => {
    if (!assignForm.order_id) { setError('Select an eligible order first.'); return }
    requestConfirmation({ title: 'Confirm delivery assignment', description: 'The shipment will be created through the existing marketplace fulfillment workflow and assigned within this business.', confirmLabel: 'Assign delivery', cancelLabel: 'Cancel', successMessage: 'Delivery assigned.' }, async () => {
      try { await api.post('/api/v1/business/delivery-management/assignments', assignForm, { headers: { 'Idempotency-Key': crypto.randomUUID() } }); setAssignForm({ order_id: '', delivery_type: 'self_delivery', staff_id: '', courier_partner_id: '', delivery_date: '', delivery_instructions: '' }); await loadAll() } catch (err) { return message(err, 'Unable to assign delivery.') }
    })
  }
  const deactivate = (item: Staff) => requestConfirmation({ title: item.status === 'active' ? 'Deactivate delivery staff' : 'Reactivate delivery staff', description: (item.status === 'active' ? 'Deactivate ' : 'Reactivate ') + (item.full_name || item.name || item.staff_code) + '? Active deliveries must be reassigned first.', confirmLabel: item.status === 'active' ? 'Deactivate' : 'Reactivate', cancelLabel: 'Cancel', tone: item.status === 'active' ? 'danger' : 'default' }, async () => { try { await api.post('/api/v1/business/delivery-management/staff/' + item.id + '/status', { status: item.status === 'active' ? 'inactive' : 'active' }); await loadAll() } catch (err) { return message(err, 'Unable to change delivery personnel status.') } })
  const deactivatePartner = (partner: Partner) => requestConfirmation({ title: 'Deactivate courier partner', description: `Deactivate ${partner.name}? Existing shipment records will remain unchanged.`, confirmLabel: 'Deactivate', cancelLabel: 'Cancel', tone: 'danger' }, async () => { try { await api.post(`/api/v1/business/delivery-management/courier-partners/${partner.id}/deactivate`); await loadAll() } catch (err) { return message(err, 'Unable to deactivate courier partner.') } })
  const updateAvailability = (item: Staff, value: string) => { void run(async () => { await api.post(`/api/v1/business/delivery-management/staff/${item.id}/availability`, { availability_status: value }) }, 'Availability updated.') }
  const updateStatus = (shipment: Shipment, status: string, proof?: File) => { void run(async () => { const backendStatus = status === 'activate_delivery' ? 'picked_up' : status; if (status === 'activate_delivery') await api.post('/api/v1/business/delivery-management/shipments/' + shipment.id + '/activate'); else if (proof) { const formData = new FormData(); formData.append('status', backendStatus); formData.append('proof_of_delivery', proof); await api.post('/api/v1/business/delivery-management/shipments/' + shipment.id + '/status', formData) } else await api.post('/api/v1/business/delivery-management/shipments/' + shipment.id + '/status', { status: backendStatus }) }, 'Delivery status updated.') }
  const reassign = (shipment: Shipment) => { if (!reassignStaff) { setError('Select a replacement delivery staff member.'); return } requestConfirmation({ title: 'Reassign delivery', description: 'Reassignment will be recorded with the reason and the previous rider will be released.', confirmLabel: 'Reassign', cancelLabel: 'Cancel' }, async () => { try { await api.post(`/api/v1/business/delivery-management/shipments/${shipment.id}/reassign`, { staff_id: reassignStaff, reason: reassignReason }); setReassignFor(null); await loadAll() } catch (err) { return message(err, 'Unable to reassign delivery.') } }) }

  return <>
    <PageHeader title="Delivery Management" description="Register delivery staff, assign eligible marketplace orders, and track fulfillment progress." action={<button type="button" onClick={() => { void refresh() }} disabled={loading} className="inline-flex items-center gap-2 rounded-[10px] border border-slate-300 bg-white px-3 py-2.5 text-sm font-semibold text-slate-700 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200"><RefreshCw size={16} className={loading ? 'animate-spin' : ''} />Refresh</button>} />
    {error && <div className="mb-4"><ErrorState message={error} /></div>}{notice && <div role="status" className="mb-4 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-800 dark:border-emerald-900/60 dark:bg-emerald-950/40 dark:text-emerald-200">{notice}</div>}
    <div className="mb-5 flex gap-1 overflow-x-auto rounded-xl border border-slate-200 bg-white p-1 dark:border-slate-800 dark:bg-slate-950">{tabs.map(({ id, label, icon: Icon }) => <button key={id} type="button" onClick={() => { setTab(id); setPage(1); setSearch(''); setError('') }} className={`inline-flex shrink-0 items-center gap-2 rounded-lg px-3 py-2 text-sm font-semibold transition ${tab === id ? 'bg-blue-600 text-white' : 'text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800'}`}><Icon size={16} />{label}</button>)}</div>
    {loading && !dashboard ? <LoadingState /> : <>
      {tab === 'dashboard' && dashboard && <DashboardPanel dashboard={dashboard} onTab={setTab} />}
      {tab === 'staff' && <StaffPanel staff={staff} lookup={lookup} search={search} setSearch={(v) => { setSearch(v); setPage(1) }} page={page} setPage={setPage} perPage={perPage} setPerPage={(v) => { setPerPage(v); setPage(1) }} showForm={showStaffForm} setShowForm={setShowStaffForm} editing={editingStaff} form={staffForm} setForm={setStaffForm} saving={saving} onEdit={(item) => { setEditingStaff(item); setStaffForm({ employee_profile_id: item.employee?.id || '', store_id: item.store?.id || '', staff_code: item.staff_code, vehicle_type: item.vehicle_type || '', vehicle_plate: item.vehicle_plate || '', delivery_role: item.delivery_role || 'delivery_staff', assignment_eligibility: item.assignment_eligibility ?? true, approval_status: item.approval_status || 'approved' }); setShowStaffForm(true) }} onSave={() => { if (!staffForm.employee_profile_id) { setError('Select an existing employee profile.'); return } void run(async () => { if (editingStaff) await api.patch(`/api/v1/business/delivery-management/staff/${editingStaff.id}`, staffForm); else await api.post('/api/v1/business/delivery-management/staff', staffForm); setStaffForm({ employee_profile_id: '', store_id: '', staff_code: '', vehicle_type: '', vehicle_plate: '', delivery_role: 'delivery_staff', assignment_eligibility: true, approval_status: 'approved' }); setEditingStaff(null); setShowStaffForm(false) }, editingStaff ? 'Delivery staff updated.' : 'Delivery staff registered.') }} onAvailability={updateAvailability} onDeactivate={deactivate} />}
      {tab === 'assign' && <ShipmentAssignmentPanel shipments={assignableShipments} lookup={lookup} search={search} setSearch={(v) => { setSearch(v); setPage(1) }} statusFilter={shipmentStatusFilter} setStatusFilter={(v) => { setShipmentStatusFilter(v); setPage(1) }} branchFilter={shipmentBranchFilter} setBranchFilter={(v) => { setShipmentBranchFilter(v); setPage(1) }} page={page} setPage={setPage} perPage={perPage} setPerPage={(v) => { setPerPage(v); setPage(1) }} saving={saving} onRefresh={() => { void loadAll() }} />}
      {tab === 'active' && <ShipmentPanel title="Active deliveries" records={active} page={page} setPage={setPage} perPage={perPage} setPerPage={(v) => { setPerPage(v); setPage(1) }} search={search} setSearch={(v) => { setSearch(v); setPage(1) }} onStatus={updateStatus} proofFiles={proofFiles} setProofFiles={setProofFiles} reassignFor={reassignFor} setReassignFor={setReassignFor} reassignStaff={reassignStaff} setReassignStaff={setReassignStaff} reassignReason={reassignReason} setReassignReason={setReassignReason} onReassign={reassign} />}
      {tab === 'history' && <ShipmentPanel title="Delivery history" records={history} page={page} setPage={setPage} perPage={perPage} setPerPage={(v) => { setPerPage(v); setPage(1) }} search={search} setSearch={(v) => { setSearch(v); setPage(1) }} />}
      {tab === 'couriers' && <CourierPanel partners={partners} editing={editingPartner} form={courierForm} setForm={setCourierForm} saving={saving} onEdit={(partner) => { setEditingPartner(partner); setCourierForm({ name: partner.name, phone: partner.phone || '', email: partner.email || '', notes: '' }) }} onCancel={() => { setEditingPartner(null); setCourierForm({ name: '', phone: '', email: '', notes: '' }) }} onDeactivate={deactivatePartner} onSave={() => { if (!courierForm.name.trim()) { setError('Enter a courier partner name.'); return } void run(async () => { if (editingPartner) await api.patch(`/api/v1/business/delivery-management/courier-partners/${editingPartner.id}`, courierForm); else await api.post('/api/v1/business/delivery-management/courier-partners', courierForm); setEditingPartner(null); setCourierForm({ name: '', phone: '', email: '', notes: '' }) }, editingPartner ? 'Courier partner updated.' : 'Courier partner saved.') }} />}
      {tab === 'reports' && <ReportPanel report={report} />}
    </>}
  </>
}

function DashboardPanel({ dashboard, onTab }: { dashboard: Dashboard; onTab: (tab: Tab) => void }) {
  const cards = [{ label: 'Active staff', value: dashboard.staff.total, detail: `${dashboard.staff.available} available`, icon: Users, accent: 'border-blue-500' }, { label: 'Eligible orders', value: dashboard.eligible_orders, detail: 'Awaiting assignment', icon: ClipboardList, accent: 'border-violet-500' }, { label: 'Active deliveries', value: dashboard.deliveries.active, detail: `${dashboard.deliveries.pending_assignment} pending assignment`, icon: Truck, accent: 'border-amber-500' }, { label: 'Delivered today', value: dashboard.deliveries.delivered_today, detail: `${dashboard.deliveries.failed} failed overall`, icon: CheckCircle2, accent: 'border-emerald-500' }]
  return <><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{cards.map(({ label, value, detail, icon: Icon, accent }) => <button key={label} type="button" onClick={() => onTab(label === 'Active staff' ? 'staff' : label === 'Eligible orders' ? 'assign' : label === 'Active deliveries' ? 'active' : 'history')} className={`rounded-xl border border-slate-200 border-l-4 ${accent} bg-white p-4 text-left shadow-sm transition hover:-translate-y-0.5 dark:border-slate-700 dark:bg-slate-900`}><div className="flex items-center justify-between"><span className="text-sm font-semibold text-slate-600 dark:text-slate-300">{label}</span><span className="rounded-xl bg-slate-100 p-2 text-blue-600 dark:bg-slate-800 dark:text-blue-300"><Icon size={20} /></span></div><p className="mt-3 text-2xl font-bold text-slate-950 dark:text-white">{value.toLocaleString()}</p><p className="mt-1 text-xs text-slate-500">{detail}</p></button>)}</div><div className="mt-5 grid gap-4 lg:grid-cols-2"><section className="rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-700 dark:bg-slate-900"><h2 className="text-base font-bold text-slate-950 dark:text-white">Availability overview</h2><div className="mt-4 grid grid-cols-3 gap-3 text-center">{[['Available', dashboard.staff.available, 'text-emerald-600'], ['Busy', dashboard.staff.busy, 'text-amber-600'], ['Off duty', dashboard.staff.off_duty, 'text-slate-500']].map(([label, value, color]) => <div key={String(label)} className="rounded-xl bg-slate-50 p-4 dark:bg-slate-950"><p className={`text-xl font-bold ${color}`}>{value as number}</p><p className="mt-1 text-xs font-semibold text-slate-500">{label}</p></div>)}</div></section><section className="rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-700 dark:bg-slate-900"><h2 className="text-base font-bold text-slate-950 dark:text-white">Next actions</h2><div className="mt-4 grid gap-2 sm:grid-cols-2"><button type="button" onClick={() => onTab('staff')} className="rounded-xl border border-slate-200 px-3 py-3 text-left text-sm font-semibold text-slate-700 hover:border-blue-300 dark:border-slate-700 dark:text-slate-200">Register delivery staff</button><button type="button" onClick={() => onTab('assign')} className="rounded-xl border border-slate-200 px-3 py-3 text-left text-sm font-semibold text-slate-700 hover:border-blue-300 dark:border-slate-700 dark:text-slate-200">Assign an eligible order</button></div></section></div></>
}

function StaffPanel({ staff, lookup, search, setSearch, page, setPage, perPage, setPerPage, showForm, setShowForm, editing, form, setForm, saving, onSave, onEdit, onAvailability, onDeactivate }: { staff: Page<Staff> | null; lookup: Lookup; search: string; setSearch: (value: string) => void; page: number; setPage: (value: number) => void; perPage: number; setPerPage: (value: number) => void; showForm: boolean; setShowForm: (value: boolean) => void; editing: Staff | null; form: { employee_profile_id: string; store_id: string; staff_code: string; vehicle_type: string; vehicle_plate: string; delivery_role: string; assignment_eligibility: boolean; approval_status: string }; setForm: (value: { employee_profile_id: string; store_id: string; staff_code: string; vehicle_type: string; vehicle_plate: string; delivery_role: string; assignment_eligibility: boolean; approval_status: string }) => void; saving: boolean; onSave: () => void; onEdit: (staff: Staff) => void; onAvailability: (staff: Staff, value: string) => void; onDeactivate: (staff: Staff) => void }) {
  if (!staff) return <LoadingState />
  const selected = lookup.employees.find((item) => item.id === form.employee_profile_id)
  return <CompleteStandaloneStaffPanel staff={staff} lookup={lookup} search={search} setSearch={setSearch} page={page} setPage={setPage} perPage={perPage} setPerPage={setPerPage} saving={saving} onSaved={() => window.location.reload()} onAvailability={onAvailability} onDeactivate={onDeactivate} />
  return <><Toolbar search={search} setSearch={setSearch} action={<button type="button" onClick={() => setShowForm(!showForm)} className="inline-flex items-center gap-2 rounded-[10px] bg-blue-600 px-3 py-2.5 text-sm font-semibold text-white"><Plus size={16} />Add staff</button>} />{showForm && <section className="mb-4 rounded-2xl border border-blue-200 bg-blue-50/50 p-4 dark:border-blue-900/60 dark:bg-blue-950/20"><div className="grid gap-3 md:grid-cols-2 lg:grid-cols-5">{editing ? <div className="rounded-[10px] border border-slate-300 bg-white px-3 py-2.5 text-sm dark:border-slate-700 dark:bg-slate-900"><span className="block text-xs font-semibold text-slate-500">Employee profile</span><span className="mt-1 block text-slate-900 dark:text-slate-100">{editing.employee?.name || editing.staff_code}</span></div> : <EmployeePicker employees={lookup.employees} value={form.employee_profile_id} onChange={(value) => setForm({ ...form, employee_profile_id: value })} />}<Field label="Branch" value={form.store_id} onChange={(value) => setForm({ ...form, store_id: value })} select options={[['', 'All branches'], ...lookup.stores.map((item) => [item.id, item.name])]} /><Field label="Vehicle type" value={form.vehicle_type} onChange={(value) => setForm({ ...form, vehicle_type: value })} placeholder="Motorbike" /><Field label="Vehicle plate (optional)" value={form.vehicle_plate} onChange={(value) => setForm({ ...form, vehicle_plate: value })} placeholder="9A-1234" /><Field label="Delivery role" value={form.delivery_role} onChange={(value) => setForm({ ...form, delivery_role: value })} select options={[['delivery_staff', 'Delivery staff'], ['delivery_lead', 'Delivery lead'], ['dispatcher', 'Dispatcher']]} /></div>{selected && <div className="mt-3 rounded-[10px] border border-slate-200 bg-white p-3 text-xs dark:border-slate-700 dark:bg-slate-900"><p className="font-bold text-slate-900 dark:text-white">{selected.name} · {selected.employee_number}</p><p className="mt-1">Job role: {selected.job_role || '—'} · Branch: {selected.branches?.map((branch) => branch.name).join(', ') || '—'}</p><p>Phone: {selected.phone || '—'} · Email: {selected.email || '—'}</p><p className="mt-1 text-emerald-700">{selected.photo_available ? 'Existing profile photo will be reused.' : 'No profile photo on file.'}</p></div>}<label className="mt-3 flex items-center gap-2 rounded-[10px] border border-slate-300 bg-white px-3 py-2.5 text-sm font-semibold dark:border-slate-700 dark:bg-slate-900"><input type="checkbox" checked={form.assignment_eligibility} onChange={(event) => setForm({ ...form, assignment_eligibility: event.target.checked })} />Eligible for delivery assignment</label><p className="mt-2 text-xs text-slate-500">Saving this configuration is manager-approved; the original employee role and profile remain unchanged.</p><div className="mt-3 flex justify-end gap-2"><button type="button" onClick={() => { setShowForm(false) }} className="rounded-[10px] border border-slate-300 px-4 py-2.5 text-sm font-semibold dark:border-slate-700">Cancel</button><button type="button" disabled={saving} onClick={onSave} className="rounded-[10px] bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60">{editing ? 'Update staff' : 'Save staff'}</button></div></section>}{!staff ? <LoadingState /> : staff.data.length === 0 ? <EmptyState label="No delivery staff found" /> : <div className="overflow-x-auto rounded-2xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900"><table className="w-full min-w-[820px] text-left text-sm"><thead className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500 dark:border-slate-700"><tr><th className="px-4 py-3">Staff</th><th className="px-4 py-3">Branch</th><th className="px-4 py-3">Vehicle</th><th className="px-4 py-3">Availability</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{staff.data.map((item) => <tr key={item.id}><td className="px-4 py-4"><p className="font-semibold text-slate-950 dark:text-white">{item.employee?.name || item.staff_code}</p><p className="mt-1 text-xs text-slate-500">{item.staff_code} · {item.employee?.phone || 'Phone private'}</p></td><td className="px-4 py-4 text-slate-600 dark:text-slate-300">{item.store?.name || 'All branches'}</td><td className="px-4 py-4 text-slate-600 dark:text-slate-300">{[item.vehicle_type, item.vehicle_plate].filter(Boolean).join(' · ') || '—'}</td><td className="px-4 py-4"><select aria-label={`Availability for ${item.employee?.name || item.staff_code}`} value={item.availability_status} onChange={(event) => onAvailability(item, event.target.value)} className="rounded-lg border border-slate-300 bg-white px-2 py-1.5 text-xs dark:border-slate-700 dark:bg-slate-950"><option value="available">Available</option><option value="busy">Busy</option><option value="off_duty">Off duty</option></select></td><td className="px-4 py-4"><StatusBadge status={item.status === 'active' ? item.availability_status : 'deactivated'} /></td><td className="px-4 py-4 text-right"><div className="flex justify-end gap-2">{item.status === 'active' && <button type="button" onClick={() => onEdit(item)} className="rounded-lg border border-slate-300 px-2.5 py-2 text-xs font-semibold text-slate-700 dark:border-slate-700 dark:text-slate-200">Edit</button>}{item.status === 'active' && <button type="button" onClick={() => onDeactivate(item)} className="inline-flex items-center gap-1 rounded-lg border border-red-200 px-2.5 py-2 text-xs font-semibold text-red-700 dark:border-red-900/60 dark:text-red-300"><UserRoundX size={14} />Deactivate</button>}</div></td></tr>)}</tbody></table></div>}{staff && <Pagination page={page} lastPage={staff.last_page} total={staff.total} perPage={perPage} setPage={setPage} setPerPage={setPerPage} />}</>
}

type StandaloneForm = { full_name: string; phone: string; email: string; emergency_contact: string; vehicle_type: string; vehicle_plate: string; branch_ids: string[]; employment_type: string; status: string; availability_status: string; max_active_assignments: string; notes: string; profile_photo?: File }

function CompleteStandaloneStaffPanel({ staff, lookup, search, setSearch, page, setPage, perPage, setPerPage, saving, onSaved, onAvailability, onDeactivate }: { staff: Page<Staff> | null; lookup: Lookup; search: string; setSearch: (value: string) => void; page: number; setPage: (value: number) => void; perPage: number; setPerPage: (value: number) => void; saving: boolean; onSaved: () => void; onAvailability: (staff: Staff, value: string) => void; onDeactivate: (staff: Staff) => void }) {
  const blank: StandaloneForm = { full_name: '', phone: '', email: '', emergency_contact: '', vehicle_type: '', vehicle_plate: '', branch_ids: [], employment_type: 'employee', status: 'active', availability_status: 'available', max_active_assignments: '1', notes: '' }
  const [form, setForm] = useState(blank); const [editing, setEditing] = useState<Staff | null>(null); const [showForm, setShowForm] = useState(false); const [detail, setDetail] = useState<Staff | null>(null); const [formError, setFormError] = useState('')
  const update = (key: keyof StandaloneForm, value: string) => setForm({ ...form, [key]: value })
  const save = async () => { if (!form.full_name.trim() || !form.phone.trim()) { setFormError('Full name and phone number are required.'); return }; const body = new FormData(); Object.entries(form).forEach(([key, value]) => { if (key !== 'branch_ids' && key !== 'profile_photo' && value !== '') body.append(key, String(value)) }); form.branch_ids.forEach((id) => body.append('branch_ids[]', id)); if (form.profile_photo) body.append('profile_photo', form.profile_photo); try { if (editing) { body.append('_method', 'PATCH'); await api.post('/api/v1/business/delivery-management/staff/' + editing.id, body) } else await api.post('/api/v1/business/delivery-management/staff', body); setShowForm(false); setEditing(null); setForm(blank); setFormError(''); onSaved() } catch (err) { setFormError(message(err, 'Unable to save delivery personnel.')) } }
  const edit = (item: Staff) => { setEditing(item); setForm({ full_name: item.full_name || item.name || '', phone: item.phone || '', email: item.email || '', emergency_contact: item.emergency_contact || '', vehicle_type: item.vehicle_type || '', vehicle_plate: item.vehicle_plate || '', branch_ids: item.branches?.map((branch) => branch.id) || (item.store ? [item.store.id] : []), employment_type: item.employment_type || 'employee', status: item.status, availability_status: item.availability_status, max_active_assignments: String(item.max_active_assignments || 1), notes: item.notes || '' }); setShowForm(true) }
  const setStatus = async (item: Staff, status: string) => { try { await api.post('/api/v1/business/delivery-management/staff/' + item.id + '/status', { status }); onSaved() } catch (err) { setFormError(message(err, 'Unable to change account status.')) } }
  const showDetail = async (item: Staff) => { try { const response = await api.get<{ data: Staff }>('/api/v1/business/delivery-management/staff/' + item.id); setDetail(response.data.data) } catch (err) { setFormError(message(err, 'Unable to load delivery profile.')) } }
  return <><Toolbar search={search} setSearch={setSearch} action={<button type="button" onClick={() => { setEditing(null); setForm(blank); setShowForm(true) }} className="inline-flex items-center gap-2 rounded-[10px] bg-blue-600 px-3 py-2.5 text-sm font-semibold text-white"><Plus size={16} />Add delivery person</button>} />
    {formError && <div className="mt-3 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{formError}</div>}
    {showForm && <section className="mt-3 rounded-2xl border border-blue-200 bg-blue-50/50 p-4 dark:border-blue-900/60 dark:bg-blue-950/20"><h2 className="font-bold text-slate-950 dark:text-white">{editing ? 'Edit delivery profile · ' + editing.staff_code : 'Register delivery person'}</h2><div className="mt-3 grid gap-3 md:grid-cols-2 lg:grid-cols-3"><Field label="Full name *" value={form.full_name} onChange={(v) => update('full_name', v)} /><Field label="Phone number *" value={form.phone} onChange={(v) => update('phone', v)} /><Field label="Email" value={form.email} onChange={(v) => update('email', v)} /><Field label="Emergency contact" value={form.emergency_contact} onChange={(v) => update('emergency_contact', v)} /><Field label="Vehicle type" value={form.vehicle_type} onChange={(v) => update('vehicle_type', v)} /><Field label="Vehicle plate" value={form.vehicle_plate} onChange={(v) => update('vehicle_plate', v)} /><Field label="Employment type" value={form.employment_type} onChange={(v) => update('employment_type', v)} select options={[['employee', 'Employee'], ['contractor', 'Contractor']]} /><Field label="Account status" value={form.status} onChange={(v) => update('status', v)} select options={[['active', 'Active'], ['inactive', 'Inactive'], ['suspended', 'Suspended']]} /><Field label="Availability" value={form.availability_status} onChange={(v) => update('availability_status', v)} select options={[['available', 'Available'], ['busy', 'Busy'], ['off_duty', 'Off duty']]} /><Field label="Assignment capacity" value={form.max_active_assignments} onChange={(v) => update('max_active_assignments', v)} /><label className="block text-sm font-semibold text-slate-700 dark:text-slate-200">Profile photo<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => setForm({ ...form, profile_photo: e.target.files?.[0] })} className={inputClass} /></label><label className="block text-sm font-semibold text-slate-700 dark:text-slate-200">Authorized branches<select multiple value={form.branch_ids} onChange={(e) => setForm({ ...form, branch_ids: Array.from(e.target.selectedOptions, (o) => o.value) })} className={inputClass}>{lookup.stores.map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></label></div><label className="mt-3 block text-sm font-semibold text-slate-700 dark:text-slate-200">Notes<textarea value={form.notes} onChange={(e) => update('notes', e.target.value)} className={inputClass} /></label><div className="mt-3 flex justify-end gap-2"><button type="button" onClick={() => setShowForm(false)} className="rounded-[10px] border border-slate-300 px-4 py-2.5 text-sm font-semibold dark:border-slate-700">Cancel</button><button type="button" disabled={saving} onClick={() => void save()} className="rounded-[10px] bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">{editing ? 'Save changes' : 'Register delivery person'}</button></div></section>}
    {detail && <section className="mt-3 rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900"><div className="flex items-start justify-between"><div><h2 className="font-bold text-slate-950 dark:text-white">{detail.full_name || detail.name}</h2><p className="text-xs text-slate-500">{detail.staff_code} · {detail.phone || 'No phone'} · {detail.email || 'No email'}</p><p className="mt-2 text-xs text-slate-500">Assignments: {detail.workload || 0}/{detail.max_active_assignments || 1} · Branches: {detail.branches?.map((b) => b.name).join(', ') || '—'}</p></div><button type="button" onClick={() => setDetail(null)} className="rounded-lg border border-slate-300 px-2 py-1 text-xs dark:border-slate-700">Close</button></div><div className="mt-3 grid gap-2 text-xs text-slate-500 md:grid-cols-2"><p>Account status: <StatusBadge status={detail.status} /></p><p>Availability: <StatusBadge status={detail.availability_status} /></p><p>Assigned orders: {detail.assigned_orders?.length || 0}</p><p>Delivery history: {detail.delivery_history?.length || 0}</p></div></section>}
    {!staff ? <LoadingState /> : staff.data.length === 0 ? <EmptyState label="No delivery personnel found." /> : <div className="mt-3 overflow-x-auto rounded-2xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900"><table className="w-full min-w-[980px] text-left text-sm"><thead className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500 dark:border-slate-700"><tr><th className="px-4 py-3">Delivery person</th><th className="px-4 py-3">Branch</th><th className="px-4 py-3">Vehicle</th><th className="px-4 py-3">Assignments</th><th className="px-4 py-3">Availability</th><th className="px-4 py-3">Account status</th><th className="px-4 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{staff.data.map((item) => <tr key={item.id}><td className="px-4 py-4"><p className="font-semibold text-slate-950 dark:text-white">{item.full_name || item.name || item.staff_code}</p><p className="text-xs text-slate-500">{item.staff_code} · {item.phone || 'Phone private'}</p></td><td className="px-4 py-4">{item.branches?.map((b) => b.name).join(', ') || item.store?.name || '—'}</td><td className="px-4 py-4">{[item.vehicle_type, item.vehicle_plate].filter(Boolean).join(' · ') || '—'}</td><td className="px-4 py-4">{item.workload || 0}/{item.max_active_assignments || 1}</td><td className="px-4 py-4"><select value={item.availability_status} onChange={(e) => onAvailability(item, e.target.value)} className="rounded-lg border border-slate-300 bg-white px-2 py-1.5 text-xs dark:border-slate-700 dark:bg-slate-950"><option value="available">Available</option><option value="busy">Busy</option><option value="off_duty">Off duty</option></select></td><td className="px-4 py-4"><StatusBadge status={item.status} /></td><td className="px-4 py-4 text-right"><div className="flex justify-end gap-1"><button type="button" onClick={() => void showDetail(item)} className="rounded-lg border border-slate-300 px-2 py-1.5 text-xs font-semibold dark:border-slate-700">View</button><button type="button" onClick={() => edit(item)} className="rounded-lg border border-slate-300 px-2 py-1.5 text-xs font-semibold dark:border-slate-700">Edit</button>{item.status === 'active' ? <button type="button" onClick={() => onDeactivate(item)} className="rounded-lg border border-red-200 px-2 py-1.5 text-xs font-semibold text-red-700">Deactivate</button> : <button type="button" onClick={() => void setStatus(item, 'active')} className="rounded-lg border border-emerald-200 px-2 py-1.5 text-xs font-semibold text-emerald-700">Activate</button>}{item.status === 'active' && <button type="button" onClick={() => void setStatus(item, 'suspended')} className="rounded-lg border border-amber-200 px-2 py-1.5 text-xs font-semibold text-amber-700">Suspend</button>}</div></td></tr>)}</tbody></table></div>}{staff && <Pagination page={page} lastPage={staff.last_page} total={staff.total} perPage={perPage} setPage={setPage} setPerPage={setPerPage} />}</>
}

function StandaloneStaffPanel({ staff, lookup, search, setSearch, page, setPage, perPage, setPerPage, saving, onSaved, onAvailability, onDeactivate }: { staff: Page<Staff> | null; lookup: Lookup; search: string; setSearch: (value: string) => void; page: number; setPage: (value: number) => void; perPage: number; setPerPage: (value: number) => void; saving: boolean; onSaved: () => void; onAvailability: (staff: Staff, value: string) => void; onDeactivate: (staff: Staff) => void }) {
  const blank: StandaloneForm = { full_name: '', phone: '', email: '', emergency_contact: '', vehicle_type: '', vehicle_plate: '', branch_ids: [], employment_type: 'employee', status: 'active', availability_status: 'available', max_active_assignments: '1', notes: '' }
  const [form, setForm] = useState(blank); const [editing, setEditing] = useState<Staff | null>(null); const [showForm, setShowForm] = useState(false); const [formError, setFormError] = useState('')
  const submit = async () => {
    if (!form.full_name.trim() || !form.phone.trim()) { setFormError('Full name and phone number are required.'); return }
    const data = new FormData(); Object.entries(form).forEach(([key, value]) => { if (key !== 'branch_ids' && key !== 'profile_photo' && value !== '') data.append(key, String(value)) }); form.branch_ids.forEach((id) => data.append('branch_ids[]', id)); if (form.profile_photo) data.append('profile_photo', form.profile_photo)
    try { if (editing) { data.append('_method', 'PATCH'); await api.post('/api/v1/business/delivery-management/staff/' + editing.id, data, { headers: { 'Content-Type': 'multipart/form-data' } }) } else await api.post('/api/v1/business/delivery-management/staff', data, { headers: { 'Content-Type': 'multipart/form-data' } }); setForm(blank); setEditing(null); setShowForm(false); onSaved() } catch (err) { setFormError(message(err, 'Unable to save delivery personnel.')) }
  }
  const edit = (item: Staff) => { setEditing(item); setForm({ full_name: item.full_name || item.name || '', phone: item.phone || '', email: item.email || '', emergency_contact: item.emergency_contact || '', vehicle_type: item.vehicle_type || '', vehicle_plate: item.vehicle_plate || '', branch_ids: item.branches?.map((branch) => branch.id) || (item.store ? [item.store.id] : []), employment_type: item.employment_type || 'employee', status: item.status, availability_status: item.availability_status, max_active_assignments: String(item.max_active_assignments || 1), notes: item.notes || '' }); setShowForm(true) }
  const changeStatus = async (item: Staff, status: string) => { try { await api.post('/api/v1/business/delivery-management/staff/' + item.id + '/status', { status }); onSaved() } catch (err) { setFormError(message(err, 'Unable to change delivery personnel status.')) } }
  const approve = async (item: Staff) => { try { await api.post('/api/v1/business/delivery-management/staff/' + item.id + '/approve'); onSaved() } catch (err) { setFormError(message(err, 'Unable to approve delivery personnel.')) } }
  const update = (key: keyof StandaloneForm, value: string) => setForm({ ...form, [key]: value })
  return <><Toolbar search={search} setSearch={setSearch} action={<button type="button" onClick={() => { setEditing(null); setForm(blank); setShowForm(!showForm) }} className="inline-flex items-center gap-2 rounded-[10px] bg-blue-600 px-3 py-2.5 text-sm font-semibold text-white"><Plus size={16} />Add delivery person</button>} />{showForm && <section className="mt-3 rounded-2xl border border-blue-200 bg-blue-50/50 p-4 dark:border-blue-900/60 dark:bg-blue-950/20"><h2 className="font-bold text-slate-950 dark:text-white">{editing ? 'Edit delivery person' : 'Register delivery person'}</h2><p className="text-xs text-slate-500">{editing ? 'Delivery Staff ID: ' + editing.staff_code : 'Delivery Staff ID is generated automatically when saved.'}</p>{formError && <p className="my-3 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{formError}</p>}<div className="mt-3 grid gap-3 md:grid-cols-2 lg:grid-cols-3"><Field label="Full name *" value={form.full_name} onChange={(v) => update('full_name', v)} /><Field label="Phone number *" value={form.phone} onChange={(v) => update('phone', v)} /><Field label="Email (optional)" value={form.email} onChange={(v) => update('email', v)} /><Field label="Emergency contact" value={form.emergency_contact} onChange={(v) => update('emergency_contact', v)} /><Field label="Vehicle type" value={form.vehicle_type} onChange={(v) => update('vehicle_type', v)} placeholder="Motorbike, bicycle, van" /><Field label="Vehicle plate (optional)" value={form.vehicle_plate} onChange={(v) => update('vehicle_plate', v)} /><Field label="Type" value={form.employment_type} onChange={(v) => update('employment_type', v)} select options={[['employee', 'Employee'], ['contractor', 'Contractor']]} /><Field label="Status" value={form.status} onChange={(v) => update('status', v)} select options={[['active', 'Active'], ['inactive', 'Inactive']]} /><Field label="Availability" value={form.availability_status} onChange={(v) => update('availability_status', v)} select options={[['available', 'Available'], ['busy', 'Busy'], ['off_duty', 'Off duty']]} /><label className="block text-sm font-semibold text-slate-700 dark:text-slate-200">Profile photo<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => setForm({ ...form, profile_photo: e.target.files?.[0] })} className={inputClass} /></label><label className="block text-sm font-semibold text-slate-700 dark:text-slate-200">Authorized branches<select multiple value={form.branch_ids} onChange={(e) => setForm({ ...form, branch_ids: Array.from(e.target.selectedOptions, (o) => o.value) })} className={inputClass}>{lookup.stores.map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></label></div><label className="mt-3 block text-sm font-semibold text-slate-700 dark:text-slate-200">Notes<textarea value={form.notes} onChange={(e) => update('notes', e.target.value)} className={inputClass} /></label><div className="mt-4 flex justify-end gap-2"><button type="button" onClick={() => setShowForm(false)} className="rounded-[10px] border border-slate-300 px-4 py-2.5 text-sm font-semibold dark:border-slate-700">Cancel</button><button type="button" disabled={saving} onClick={() => void submit()} className="rounded-[10px] bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60">{editing ? 'Save changes' : 'Register delivery person'}</button></div></section>}{!staff ? <LoadingState /> : staff.data.length === 0 ? <EmptyState label="No delivery personnel found. Use Add delivery person to register the first one." /> : <div className="mt-3 overflow-x-auto rounded-2xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900"><table className="w-full min-w-[900px] text-left text-sm"><thead className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500 dark:border-slate-700"><tr><th className="px-4 py-3">Delivery person</th><th className="px-4 py-3">Branch</th><th className="px-4 py-3">Vehicle</th><th className="px-4 py-3">Workload</th><th className="px-4 py-3">Availability</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{staff.data.map((item) => <tr key={item.id}><td className="px-4 py-4"><p className="font-semibold text-slate-950 dark:text-white">{item.full_name || item.name || item.staff_code}</p><p className="mt-1 text-xs text-slate-500">{item.staff_code} · {item.phone || 'Phone private'}</p></td><td className="px-4 py-4">{item.branches?.map((b) => b.name).join(', ') || item.store?.name || '—'}</td><td className="px-4 py-4">{[item.vehicle_type, item.vehicle_plate].filter(Boolean).join(' · ') || '—'}</td><td className="px-4 py-4">{item.workload ?? 0}</td><td className="px-4 py-4"><select value={item.availability_status} onChange={(e) => onAvailability(item, e.target.value)} className="rounded-lg border border-slate-300 bg-white px-2 py-1.5 text-xs dark:border-slate-700 dark:bg-slate-950"><option value="available">Available</option><option value="busy">Busy</option><option value="off_duty">Off duty</option></select></td><td className="px-4 py-4"><StatusBadge status={item.status === 'active' ? item.availability_status : 'inactive'} /></td><td className="px-4 py-4 text-right">{item.status === 'active' && <><button type="button" onClick={() => edit(item)} className="mr-2 rounded-lg border border-slate-300 px-2.5 py-2 text-xs font-semibold dark:border-slate-700">Edit</button><button type="button" onClick={() => onDeactivate(item)} className="rounded-lg border border-red-200 px-2.5 py-2 text-xs font-semibold text-red-700">Deactivate</button></>}</td></tr>)}</tbody></table></div>}{staff && <Pagination page={page} lastPage={staff.last_page} total={staff.total} perPage={perPage} setPage={setPage} setPerPage={setPerPage} />}</>
}

function EmployeePicker({ employees, value, onChange }: { employees: EmployeeOption[]; value: string; onChange: (value: string) => void }) {
  const [query, setQuery] = useState('')
  const selected = employees.find((employee) => employee.id === value)
  const filtered = employees.filter((employee) => `${employee.name} ${employee.employee_number} ${employee.job_role || ''} ${employee.branches?.map((branch) => branch.name).join(' ') || ''}`.toLowerCase().includes(query.toLowerCase()))
  return <div className="relative"><label className="block text-sm font-semibold text-slate-700 dark:text-slate-200">Existing employee profile<input aria-label="Search existing employee profiles" value={selected && !query ? `${selected.name} · ${selected.employee_number}` : query} onChange={(event) => { setQuery(event.target.value); if (value) onChange('') }} placeholder="Search name, Employee ID, role, or branch" className={`${inputClass} mt-1 border-slate-300`} /></label><div className="mt-1 max-h-48 overflow-y-auto rounded-[10px] border border-slate-300 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-900">{employees.length === 0 ? <div className="p-3 text-xs text-slate-500">No employees found. <a className="font-semibold text-blue-600 underline" href="/business/staff">Add Employee</a></div> : filtered.length === 0 ? <div className="p-3 text-xs text-slate-500">No matching employees.</div> : filtered.map((employee) => <button type="button" key={employee.id} onClick={() => { onChange(employee.id); setQuery('') }} className="block w-full border-b border-slate-100 px-3 py-2 text-left text-xs last:border-b-0 hover:bg-blue-50 dark:border-slate-800 dark:hover:bg-slate-950"><span className="font-semibold text-slate-900 dark:text-white">{employee.name}</span><span className="ml-2 text-slate-500">{employee.employee_number} · {employee.job_role || 'No role'} · {employee.branches?.map((branch) => branch.name).join(', ') || 'No branch'}</span></button>)}</div></div>
}

function ShipmentAssignmentPanel({ shipments, lookup, search, setSearch, statusFilter, setStatusFilter, branchFilter, setBranchFilter, page, setPage, perPage, setPerPage, saving, onRefresh }: { shipments: Page<Shipment> | null; lookup: Lookup; search: string; setSearch: (value: string) => void; statusFilter: string; setStatusFilter: (value: string) => void; branchFilter: string; setBranchFilter: (value: string) => void; page: number; setPage: (value: number) => void; perPage: number; setPerPage: (value: number) => void; saving: boolean; onRefresh: () => void }) {
  const { requestConfirmation } = useConfirmation()
  const [selected, setSelected] = useState<Shipment | null>(null)
  const [staff, setStaff] = useState<Staff[]>([])
  const [staffId, setStaffId] = useState('')
  const [instructions, setInstructions] = useState('')
  const [reassignReason, setReassignReason] = useState('')
  const [reassigning, setReassigning] = useState(false)
  const [staffLoading, setStaffLoading] = useState(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [showHistory, setShowHistory] = useState(false)

  useEffect(() => {
    if (!selected) { setStaff([]); setStaffId(''); return }
    setStaffLoading(true); setError('')
    const endpoint = selected.assignment_status === 'pending_assignment' && !selected.staff
      ? `/api/v1/business/delivery-management/shipments/${selected.id}/eligible-staff`
      : '/api/v1/business/delivery-management/staff'
    const params = endpoint.includes('eligible-staff') ? undefined : { status: 'active', store_id: selected.branch?.id || undefined, per_page: 100 }
    void api.get<{ data: Staff[] | Page<Staff> }>(endpoint, { params }).then((response) => {
      const payload = response.data.data
      const list = Array.isArray(payload) ? payload : payload.data
      setStaff(list.filter((item) => item.status === 'active' && item.availability_status !== 'off_duty' && item.approval_status === 'approved' && item.assignment_eligibility))
    }).catch((err) => setError(message(err, 'Unable to load eligible delivery staff.'))).finally(() => setStaffLoading(false))
  }, [selected?.id, selected?.assignment_status, selected?.staff?.id, lookup])

  const applyResponse = (response: { data: { data: Shipment } }) => { setSelected(response.data.data); setStaffId(response.data.data.staff?.id || ''); onRefresh() }
  const assign = async () => {
    if (!selected || !staffId) { setError('Select an eligible delivery person.'); return }
    setError(''); setNotice('')
    try {
      const response = await api.post<{ data: Shipment }>('/api/v1/business/delivery-management/shipment-assignments', { shipment_id: selected.id, staff_id: staffId, delivery_instructions: instructions }, { headers: { 'Idempotency-Key': crypto.randomUUID() } })
      applyResponse(response); setNotice('Shipment assigned successfully.'); setInstructions('')
    } catch (err) { setError(message(err, 'Unable to assign shipment.')) }
  }
  const update = async (status: string) => {
    if (!selected) return
    setError(''); setNotice('')
    try {
      const endpoint = status === 'activate_delivery' ? `/api/v1/business/delivery-management/shipments/${selected.id}/activate` : `/api/v1/business/delivery-management/shipments/${selected.id}/status`
      const response = await api.post<{ data: Shipment }>(endpoint, status === 'activate_delivery' ? {} : { status })
      applyResponse(response); setNotice(status === 'delivered' ? 'Delivery marked as delivered.' : 'Shipment status updated.')
    } catch (err) { setError(message(err, 'Unable to update shipment status.')) }
  }
  const reassign = async () => {
    if (!selected || !staffId || !reassignReason.trim()) { setError('Select replacement staff and enter a reassignment reason.'); return }
    requestConfirmation({ title: 'Reassign delivery', description: 'The reassignment and reason will be recorded in the shipment history.', confirmLabel: 'Reassign delivery', cancelLabel: 'Cancel' }, async () => {
      try {
        setReassigning(true)
        const response = await api.post<{ data: Shipment }>(`/api/v1/business/delivery-management/shipments/${selected.id}/reassign`, { staff_id: staffId, reason: reassignReason.trim() })
        applyResponse(response); setNotice('Delivery reassigned successfully.'); setReassignReason('')
      } catch (err) { return message(err, 'Unable to reassign delivery.') } finally { setReassigning(false) }
    })
  }
  const shipmentOptions = shipments?.data || []
  const assigned = Boolean(selected?.staff)
  const terminal = selected ? ['delivered', 'cancelled', 'delivery_failed', 'returned'].includes(selected.status) : false
  const actionStatuses = selected ? nextStatus(selected.assignment_status, selected.status) : []
  return <>
    <div className="grid gap-2 md:grid-cols-[minmax(220px,1fr)_170px_190px]">
      <Toolbar search={search} setSearch={setSearch} />
      <select aria-label="Shipment status filter" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)} className={inputClass.replace('mt-1 ', '')}><option value="">All eligible statuses</option><option value="ready">Ready</option><option value="shipped">Shipped</option><option value="in_transit">In transit</option></select>
      <select aria-label="Shipment branch filter" value={branchFilter} onChange={(event) => setBranchFilter(event.target.value)} className={inputClass.replace('mt-1 ', '')}><option value="">All authorized branches</option>{lookup.stores.map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select>
    </div>
    {error && <div role="alert" className="mt-3 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700 dark:border-red-900/60 dark:bg-red-950/30 dark:text-red-200">{error}</div>}
    {notice && <div role="status" className="mt-3 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-sm text-emerald-700 dark:border-emerald-900/60 dark:bg-emerald-950/30 dark:text-emerald-200">{notice}</div>}
    <div className="mt-3 grid gap-4 xl:grid-cols-[minmax(0,1fr)_390px]">
      <section className="rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900">
        <label className="block text-sm font-semibold text-slate-700 dark:text-slate-200">Select shipment
          <select aria-label="Select shipment" value={selected?.id || ''} onChange={(event) => { const next = shipmentOptions.find((item) => item.id === event.target.value) || null; setSelected(next); setStaffId(''); setShowHistory(false); setError(''); setNotice('') }} className={`${inputClass} mt-1`}>
            <option value="">Choose an unassigned shipment</option>
            {shipmentOptions.map((shipment) => <option key={shipment.id} value={shipment.id}>{shipment.order?.order_number || shipment.order?.vendor_order_number || shipment.internal_tracking_id || shipment.id} · {shipment.branch?.name || 'Branch pending'} · {shipment.status}</option>)}
          </select>
        </label>
        <p className="mt-2 text-xs text-slate-500">Search above narrows this server-paginated shipment list. Completed, cancelled, and already assigned shipments are excluded.</p>
        {!shipments ? <LoadingState /> : shipments.data.length === 0 ? <EmptyState label="No eligible unassigned shipments found" /> : <div className="mt-3 space-y-2">{shipments.data.map((shipment) => <button type="button" key={shipment.id} onClick={() => { setSelected(shipment); setStaffId(''); setShowHistory(false); setError(''); setNotice('') }} className={`w-full rounded-xl border p-3 text-left transition ${selected?.id === shipment.id ? 'border-blue-500 bg-blue-50/60 dark:bg-blue-950/20' : 'border-slate-200 bg-white hover:border-blue-300 dark:border-slate-700 dark:bg-slate-900'}`}><div className="flex items-start justify-between gap-3"><div><p className="font-semibold text-slate-950 dark:text-white">{shipment.order?.order_number || shipment.order?.vendor_order_number || shipment.internal_tracking_id || shipment.id}</p><p className="mt-1 text-xs text-slate-500">Shipment {shipment.id.slice(0, 12)} · {shipment.order?.customer_name || 'Customer unavailable'}</p><p className="mt-1 text-xs text-slate-500">{formatAddress(shipment.order?.delivery_address)}</p></div><div className="text-right"><StatusBadge status={shipment.status} /><p className="mt-1 text-xs text-slate-500">{shipment.assignment_status}</p></div></div></button>)}</div>}
        {shipments && <Pagination page={page} lastPage={shipments.last_page} total={shipments.total} perPage={perPage} setPage={setPage} setPerPage={setPerPage} />}
      </section>
      <section className="h-fit rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900">
        <div className="flex items-start justify-between gap-3"><h2 className="font-bold text-slate-950 dark:text-white">Assignment details</h2>{selected && assigned && <button type="button" onClick={() => setShowHistory(!showHistory)} className="rounded-lg border border-slate-300 px-2.5 py-1.5 text-xs font-semibold dark:border-slate-700">{showHistory ? 'Hide history' : 'View assignment'}</button>}</div>
        {!selected ? <p className="mt-3 text-sm text-slate-500">Select a shipment to view the customer delivery details and eligible staff.</p> : <>
          <div className="mt-3 rounded-lg border border-slate-200 p-3 text-xs dark:border-slate-700"><p className="font-semibold text-slate-900 dark:text-white">Order {selected.order?.order_number || selected.order?.vendor_order_number || '—'}</p><p className="mt-1 text-slate-500">Shipment ID: {selected.id}</p><p className="mt-1 text-slate-500">{selected.order?.customer_name || 'Customer unavailable'} · {selected.branch?.name || 'Branch unavailable'}</p><p className="mt-1 text-slate-500">{formatAddress(selected.order?.delivery_address)}</p><div className="mt-2 flex flex-wrap gap-2"><StatusBadge status={selected.status} /><StatusBadge status={selected.assignment_status} /></div></div>
          {selected.staff && <div className="mt-3 rounded-lg border border-blue-200 bg-blue-50/50 p-3 text-xs dark:border-blue-900/60 dark:bg-blue-950/20"><p className="font-semibold text-slate-900 dark:text-white">Assigned: {selected.staff.name} · {selected.staff.staff_code}</p><p className="mt-1 text-slate-500">{selected.staff.vehicle_type || 'Vehicle not set'}{selected.staff.vehicle_plate ? ` · ${selected.staff.vehicle_plate}` : ''} · {selected.staff.active_assignments ?? 0}/{selected.staff.max_active_assignments ?? 1} active assignments</p></div>}
          {!assigned && <><label className="mt-3 block text-sm font-semibold text-slate-700 dark:text-slate-200">Choose delivery staff<select value={staffId} onChange={(event) => setStaffId(event.target.value)} disabled={staffLoading} className={inputClass}><option value="">{staffLoading ? 'Loading eligible staff…' : 'Select eligible delivery person'}</option>{staff.map((item) => <option key={item.id} value={item.id}>{item.full_name || item.name || item.staff_code} · {item.staff_code} · {item.vehicle_type || 'No vehicle'} · {item.availability_status} · {item.workload || 0}/{item.max_active_assignments || 1}</option>)}</select></label><label className="mt-3 block text-sm font-semibold text-slate-700 dark:text-slate-200">Delivery instructions<textarea value={instructions} onChange={(event) => setInstructions(event.target.value)} className={`${inputClass} min-h-20`} /></label><button type="button" disabled={saving || staffLoading || !staffId} onClick={() => void assign()} className="mt-3 w-full rounded-[10px] bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60">Assign Delivery</button></>}
          {assigned && !terminal && <><div className="mt-3 grid gap-2 sm:grid-cols-2">{selected.assignment_status === 'assigned' && <button type="button" onClick={() => void update('accepted')} className="rounded-[10px] border border-blue-300 px-3 py-2 text-xs font-semibold text-blue-700 dark:text-blue-300">Confirm Assignment</button>}{selected.assignment_status === 'accepted' && <button type="button" onClick={() => void update('activate_delivery')} className="rounded-[10px] bg-blue-600 px-3 py-2 text-xs font-semibold text-white">Start Delivery</button>}{actionStatuses.includes('in_transit') && <button type="button" onClick={() => void update('in_transit')} className="rounded-[10px] border border-amber-300 px-3 py-2 text-xs font-semibold text-amber-700">Update: In Transit</button>}{actionStatuses.includes('delivered') && <button type="button" onClick={() => void update('delivered')} className="rounded-[10px] border border-emerald-300 px-3 py-2 text-xs font-semibold text-emerald-700">Confirm Delivered</button>}{actionStatuses.includes('failed') && <button type="button" onClick={() => void update('failed')} className="rounded-[10px] border border-red-300 px-3 py-2 text-xs font-semibold text-red-700">Fail Delivery</button>}<button type="button" onClick={() => setReassigning(!reassigning)} className="rounded-[10px] border border-slate-300 px-3 py-2 text-xs font-semibold dark:border-slate-700">Reassign Rider</button></div>{reassigning && <div className="mt-3 rounded-xl border border-slate-200 bg-slate-50 p-3 dark:border-slate-700 dark:bg-slate-950"><label className="block text-xs font-semibold text-slate-600 dark:text-slate-300">Replacement staff<select value={staffId} onChange={(event) => setStaffId(event.target.value)} disabled={staffLoading} className={inputClass.replace('mt-1 ', '')}><option value="">Select replacement</option>{staff.map((item) => <option key={item.id} value={item.id}>{item.full_name || item.name || item.staff_code} · {item.availability_status} · {item.workload || 0}/{item.max_active_assignments || 1}</option>)}</select></label><label className="mt-2 block text-xs font-semibold text-slate-600 dark:text-slate-300">Reason<input value={reassignReason} onChange={(event) => setReassignReason(event.target.value)} className={inputClass.replace('mt-1 ', '')} /></label><button type="button" disabled={saving || !staffId || !reassignReason.trim()} onClick={() => void reassign()} className="mt-2 rounded-[10px] bg-blue-600 px-3 py-2 text-xs font-semibold text-white disabled:opacity-60">Save reassignment</button></div>}</>}
          {terminal && <p className="mt-3 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-700 dark:border-emerald-900/60 dark:bg-emerald-950/30 dark:text-emerald-200">Delivery completed or closed. No new assignment action is available.</p>}
          {showHistory && <div className="mt-3 border-t border-slate-200 pt-3 dark:border-slate-700"><h3 className="text-xs font-bold uppercase tracking-wide text-slate-500">Assignment history</h3><div className="mt-2 space-y-2">{selected.events?.length ? selected.events.map((event) => <div key={event.id} className="rounded-lg bg-slate-50 p-2 text-xs dark:bg-slate-950"><p className="font-semibold text-slate-800 dark:text-slate-200">{event.type.replaceAll('_', ' ')}</p><p className="text-slate-500">{event.event_time ? new Date(event.event_time).toLocaleString() : '—'} · {event.actor_name || 'Authorized manager'}</p>{(event.reason || event.notes) && <p className="mt-1 text-slate-600 dark:text-slate-300">{event.reason || event.notes}</p>}</div>) : <p className="text-xs text-slate-500">No assignment events recorded.</p>}</div></div>}
        </>}
      </section>
    </div>
  </>
}

function AssignPanel({ orders, lookup, form, setForm, search, setSearch, page, setPage, perPage, setPerPage, saving, onAssign }: { orders: Page<Order> | null; lookup: Lookup; form: { order_id: string; delivery_type: string; staff_id: string; courier_partner_id: string; delivery_date: string; delivery_instructions: string }; setForm: (value: { order_id: string; delivery_type: string; staff_id: string; courier_partner_id: string; delivery_date: string; delivery_instructions: string }) => void; search: string; setSearch: (value: string) => void; page: number; setPage: (value: number) => void; perPage: number; setPerPage: (value: number) => void; saving: boolean; onAssign: () => void }) {
  return <><div className="grid gap-4 xl:grid-cols-[1fr_360px]"><section><Toolbar search={search} setSearch={setSearch} /><div className="mt-3 space-y-2">{orders?.data.map((order) => <button key={order.id} type="button" onClick={() => setForm({ ...form, order_id: order.id })} className={`w-full rounded-xl border bg-white p-4 text-left transition dark:bg-slate-900 ${form.order_id === order.id ? 'border-blue-500 ring-2 ring-blue-100 dark:ring-blue-950' : 'border-slate-200 hover:border-blue-300 dark:border-slate-700'}`}><div className="flex items-start justify-between gap-3"><div><p className="font-semibold text-slate-950 dark:text-white">{order.vendor_order_number}</p><p className="mt-1 text-xs text-slate-500">{order.order_number || 'Marketplace order'} · {order.customer_name || 'Customer unavailable'}</p><p className="mt-2 flex items-center gap-1 text-xs text-slate-500"><MapPin size={13} />{formatAddress(order.delivery_address)}</p></div><span className="font-bold text-slate-900 dark:text-white">{order.total ?? '—'} {order.currency_code || 'MMK'}</span></div></button>)}{orders && orders.data.length === 0 && <EmptyState label="No eligible orders awaiting delivery" />}{!orders && <LoadingState />}</div>{orders && <Pagination page={page} lastPage={orders.last_page} total={orders.total} perPage={perPage} setPage={setPage} setPerPage={setPerPage} />}</section><section className="h-fit rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900"><h2 className="font-bold text-slate-950 dark:text-white">Assignment details</h2><label className="mt-4 block text-sm font-semibold text-slate-700 dark:text-slate-200">Delivery method<select value={form.delivery_type} onChange={(event) => setForm({ ...form, delivery_type: event.target.value, staff_id: '', courier_partner_id: '' })} className={inputClass}><option value="self_delivery">Self delivery</option><option value="external_courier">External courier</option><option value="customer_pickup">Customer pickup</option></select></label>{form.delivery_type === 'external_courier' && <Field label="Courier partner" value={form.courier_partner_id} onChange={(value) => setForm({ ...form, courier_partner_id: value })} select options={[['', 'Select courier partner'], ...lookup.partners.filter((item) => item.status !== 'inactive').map((item) => [item.id, item.name])]} />}{form.delivery_type === 'self_delivery' && <StaffSelector lookup={lookup} value={form.staff_id} onChange={(value) => setForm({ ...form, staff_id: value })} />}{form.delivery_type !== 'customer_pickup' && <label className="mt-3 block text-sm font-semibold text-slate-700 dark:text-slate-200">Delivery date<input type="date" value={form.delivery_date} onChange={(event) => setForm({ ...form, delivery_date: event.target.value })} className={inputClass} /></label>}<label className="mt-3 block text-sm font-semibold text-slate-700 dark:text-slate-200">Instructions<textarea value={form.delivery_instructions} onChange={(event) => setForm({ ...form, delivery_instructions: event.target.value })} className={`${inputClass} min-h-24`} /></label><button type="button" disabled={saving || !form.order_id} onClick={onAssign} className="mt-4 inline-flex w-full items-center justify-center gap-2 rounded-[10px] bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60"><PackageCheck size={16} />Confirm assignment</button></section></div></>
}

function StaffSelector({ lookup, value, onChange }: { lookup: Lookup; value: string; onChange: (value: string) => void }) {
  const [items, setItems] = useState<Staff[]>([])
  useEffect(() => { void api.get<{ data: Page<Staff> }>('/api/v1/business/delivery-management/staff', { params: { status: 'active', per_page: 100 } }).then((response) => setItems(response.data.data.data.filter((item) => item.availability_status !== 'off_duty' && item.approval_status === 'approved' && item.assignment_eligibility))).catch(() => setItems([])) }, [lookup])
  return <label className="mt-3 block text-sm font-semibold text-slate-700 dark:text-slate-200">Available delivery staff<select value={value} onChange={(event) => onChange(event.target.value)} className={inputClass}><option value="">Select available staff</option>{items.map((item) => <option key={item.id} value={item.id}>{item.employee?.name || item.staff_code}{item.store?.name ? ` · ${item.store.name}` : ''}</option>)}</select></label>
}

function ShipmentPanel({ title, records, page, setPage, perPage, setPerPage, search, setSearch, onStatus, proofFiles = {}, setProofFiles, reassignFor, setReassignFor, reassignStaff, setReassignStaff, reassignReason, setReassignReason, onReassign }: { title: string; records: Page<Shipment> | null; page: number; setPage: (value: number) => void; perPage: number; setPerPage: (value: number) => void; search: string; setSearch: (value: string) => void; onStatus?: (shipment: Shipment, status: string, proof?: File) => void; proofFiles?: Record<string, File | undefined>; setProofFiles?: (value: Record<string, File | undefined>) => void; reassignFor?: string | null; setReassignFor?: (value: string | null) => void; reassignStaff?: string; setReassignStaff?: (value: string) => void; reassignReason?: string; setReassignReason?: (value: string) => void; onReassign?: (shipment: Shipment) => void }) {
  return <><Toolbar search={search} setSearch={setSearch} />{!records ? <LoadingState /> : records.data.length === 0 ? <EmptyState label={`No ${title.toLowerCase()} found`} /> : <div className="mt-3 space-y-3">{records.data.map((shipment) => <article key={shipment.id} className="rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-semibold text-slate-950 dark:text-white">{shipment.order?.vendor_order_number || shipment.internal_tracking_id}</p><p className="mt-1 text-xs text-slate-500">{shipment.order?.customer_name || 'Customer unavailable'} · {shipment.staff?.name || shipment.courier_partner?.name || shipment.delivery_type.replaceAll('_', ' ')}</p><p className="mt-2 text-xs text-slate-500">{formatAddress(shipment.order?.delivery_address)}{shipment.delivery_notes ? ` · ${shipment.delivery_notes}` : ''}</p></div><div className="text-right"><StatusBadge status={shipment.assignment_status || shipment.status} /><p className="mt-2 text-sm font-bold text-slate-900 dark:text-white">{shipment.order?.total ?? '—'} {shipment.order?.currency_code || 'MMK'}</p></div></div><div className="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-slate-100 pt-3 text-xs text-slate-500 dark:border-slate-800"><span>Created {shipment.created_at ? new Date(shipment.created_at).toLocaleString() : '—'} · {shipment.tracking_number || shipment.internal_tracking_id || 'No tracking number'}</span>{onStatus && <div className="flex flex-wrap items-center gap-2">{nextStatus(shipment.assignment_status, shipment.status).map((status) => <button key={status} type="button" onClick={() => onStatus(shipment, status, proofFiles[shipment.id])} className="rounded-lg bg-blue-600 px-3 py-2 text-xs font-semibold text-white">{status.replaceAll('_', ' ')}</button>)}{nextStatus(shipment.assignment_status, shipment.status).includes('delivered') && <label className="inline-flex cursor-pointer items-center gap-1 rounded-lg border border-slate-300 px-2 py-2 text-xs font-semibold text-slate-600 dark:border-slate-700 dark:text-slate-300">Proof<input type="file" accept="image/jpeg,image/png,application/pdf" className="sr-only" onChange={(event) => setProofFiles?.({ ...proofFiles, [shipment.id]: event.target.files?.[0] })} /></label>}{shipment.delivery_type === 'self_delivery' && !['delivered', 'cancelled', 'delivery_failed', 'returned'].includes(shipment.status) && <button type="button" onClick={() => setReassignFor?.(shipment.id)} className="rounded-lg border border-slate-300 px-3 py-2 text-xs font-semibold text-slate-700 dark:border-slate-700 dark:text-slate-200">Reassign</button>}</div>}</div>{reassignFor === shipment.id && <div className="mt-3 grid gap-2 rounded-xl bg-slate-50 p-3 dark:bg-slate-950 sm:grid-cols-[1fr_1fr_auto]"><select value={reassignStaff} onChange={(event) => setReassignStaff?.(event.target.value)} className={inputClass.replace('mt-1 ', '')}><option value="">Replacement staff</option><AvailableStaffOptions /></select><input value={reassignReason} onChange={(event) => setReassignReason?.(event.target.value)} className={inputClass.replace('mt-1 ', '')} aria-label="Reassignment reason" /><button type="button" onClick={() => onReassign?.(shipment)} className="rounded-[10px] bg-blue-600 px-3 py-2 text-xs font-semibold text-white">Save</button></div>}</article>)}</div>}{records && <Pagination page={page} lastPage={records.last_page} total={records.total} perPage={perPage} setPage={setPage} setPerPage={setPerPage} />}</>
}

function AvailableStaffOptions() { const [items, setItems] = useState<Staff[]>([]); useEffect(() => { void api.get<{ data: Page<Staff> }>('/api/v1/business/delivery-management/staff', { params: { status: 'active', per_page: 100 } }).then((response) => setItems(response.data.data.data.filter((item) => item.availability_status !== 'off_duty' && item.approval_status === 'approved' && item.assignment_eligibility))).catch(() => setItems([])) }, []); return <>{items.map((item) => <option key={item.id} value={item.id}>{item.full_name || item.name || item.employee?.name || item.staff_code} · {item.availability_status} · {item.workload ?? 0}/{item.max_active_assignments || 1}</option>)}</> }

function CourierPanel({ partners, editing, form, setForm, saving, onSave, onEdit, onCancel, onDeactivate }: { partners: Partner[]; editing: Partner | null; form: { name: string; phone: string; email: string; notes: string }; setForm: (value: { name: string; phone: string; email: string; notes: string }) => void; saving: boolean; onSave: () => void; onEdit: (partner: Partner) => void; onCancel: () => void; onDeactivate: (partner: Partner) => void }) { return <div className="grid gap-4 lg:grid-cols-[360px_1fr]"><section className="rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900"><h2 className="font-bold text-slate-950 dark:text-white">{editing ? 'Edit courier partner' : 'Add courier partner'}</h2><Field label="Name" value={form.name} onChange={(value) => setForm({ ...form, name: value })} /><Field label="Phone" value={form.phone} onChange={(value) => setForm({ ...form, phone: value })} /><Field label="Email" value={form.email} onChange={(value) => setForm({ ...form, email: value })} /><label className="mt-3 block text-sm font-semibold text-slate-700 dark:text-slate-200">Notes<textarea value={form.notes} onChange={(event) => setForm({ ...form, notes: event.target.value })} className={`${inputClass} min-h-24`} /></label><div className="mt-4 flex gap-2"><button type="button" onClick={onSave} disabled={saving} className="w-full rounded-[10px] bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60">{editing ? 'Update partner' : 'Save partner'}</button>{editing && <button type="button" onClick={onCancel} className="rounded-[10px] border border-slate-300 px-3 py-2.5 text-sm font-semibold dark:border-slate-700">Cancel</button>}</div></section><section className="rounded-2xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900"><div className="border-b border-slate-200 p-4 dark:border-slate-700"><h2 className="font-bold text-slate-950 dark:text-white">Configured partners</h2></div>{partners.length === 0 ? <EmptyState label="No courier partners configured" /> : <div className="divide-y divide-slate-100 dark:divide-slate-800">{partners.map((partner) => <div key={partner.id} className="flex items-center justify-between gap-3 p-4"><div><p className="font-semibold text-slate-900 dark:text-white">{partner.name}</p><p className="mt-1 text-xs text-slate-500">{partner.phone || partner.email || 'Contact details not provided'}</p></div><div className="flex items-center gap-2"><StatusBadge status={partner.status || 'active'} />{partner.status !== 'inactive' && <><button type="button" onClick={() => onEdit(partner)} className="rounded-lg border border-slate-300 px-2.5 py-1.5 text-xs font-semibold dark:border-slate-700">Edit</button><button type="button" onClick={() => onDeactivate(partner)} className="rounded-lg border border-red-200 px-2.5 py-1.5 text-xs font-semibold text-red-700 dark:border-red-900/60 dark:text-red-300">Deactivate</button></>}</div></div>)}</div>}</section></div> }

function ReportPanel({ report }: { report: Report | null }) { if (!report) return <LoadingState />; const cards: Array<{ label: string; value: number; icon: LucideIcon }> = [{ label: 'Total deliveries', value: report.summary.total, icon: ClipboardList }, { label: 'Delivered', value: report.summary.delivered, icon: CheckCircle2 }, { label: 'Failed', value: report.summary.failed, icon: XCircle }, { label: 'Active', value: report.summary.active, icon: Clock3 }]; return <><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{cards.map(({ label, value, icon: Icon }) => <div key={label} className="rounded-xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-slate-900"><Icon className="text-blue-600" size={20} /><p className="mt-3 text-2xl font-bold text-slate-950 dark:text-white">{value}</p><p className="mt-1 text-sm text-slate-500">{label}</p></div>)}</div><div className="mt-4 overflow-x-auto rounded-2xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900"><table className="w-full min-w-[560px] text-left text-sm"><thead className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500 dark:border-slate-700"><tr><th className="px-4 py-3">Staff</th><th className="px-4 py-3">Total</th><th className="px-4 py-3">Delivered</th><th className="px-4 py-3">Failed</th></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{report.staff.map((item) => <tr key={item.id}><td className="px-4 py-3 font-semibold text-slate-900 dark:text-white">{item.name}</td><td className="px-4 py-3 text-slate-600 dark:text-slate-300">{item.total}</td><td className="px-4 py-3 text-emerald-600">{item.delivered}</td><td className="px-4 py-3 text-red-600">{item.failed}</td></tr>)}</tbody></table></div></> }

function Toolbar({ search, setSearch, action }: { search: string; setSearch: (value: string) => void; action?: ReactNode }) { return <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><label className="relative block w-full sm:max-w-sm"><span className="sr-only">Search delivery records</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search delivery records..." className={`${inputClass} mt-0 pl-3`} /></label>{action}</div> }
function Field({ label, value, onChange, placeholder, select, options }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; select?: boolean; options?: Array<string[]> }) { return <label className="block text-sm font-semibold text-slate-700 dark:text-slate-200">{label}{select ? <select value={value} onChange={(event) => onChange(event.target.value)} className={inputClass}>{options?.map(([optionValue, optionLabel]) => <option key={`${optionValue}-${optionLabel}`} value={optionValue}>{optionLabel}</option>)}</select> : <input value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className={inputClass} />}</label> }
function Pagination({ page, lastPage, total, perPage, setPage, setPerPage }: { page: number; lastPage: number; total: number; perPage: number; setPage: (value: number) => void; setPerPage: (value: number) => void }) { return <div className="mt-4 flex flex-wrap items-center justify-between gap-3 text-sm text-slate-500"><span>{total.toLocaleString()} records</span><div className="flex items-center gap-2"><label className="flex items-center gap-2">Rows<select value={perPage} onChange={(event) => setPerPage(Number(event.target.value))} className="rounded-lg border border-slate-300 bg-white px-2 py-1.5 text-xs dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100">{[10, 20, 50, 100].map((size) => <option key={size} value={size}>{size}</option>)}</select></label><button type="button" disabled={page <= 1} onClick={() => setPage(page - 1)} className="rounded-lg border border-slate-300 px-3 py-1.5 text-xs font-semibold disabled:opacity-40 dark:border-slate-700">Previous</button><span>{page} / {lastPage || 1}</span><button type="button" disabled={page >= lastPage} onClick={() => setPage(page + 1)} className="rounded-lg border border-slate-300 px-3 py-1.5 text-xs font-semibold disabled:opacity-40 dark:border-slate-700">Next</button></div></div> }
function formatAddress(address: Record<string, unknown> | string | null | undefined): string { if (!address) return 'Address unavailable'; if (typeof address === 'string') return address; return Object.values(address).filter(Boolean).join(', ') || 'Address unavailable' }
function nextStatus(assignment: string, shipment: string): string[] { if (shipment === 'ready' && assignment === 'assigned') return ['accepted']; if (assignment === 'accepted') return ['activate_delivery']; if (assignment === 'picked_up' || shipment === 'shipped') return ['in_transit']; if (assignment === 'in_transit' || shipment === 'in_transit') return ['delivered', 'failed']; if (shipment === 'delivery_failed') return ['in_transit', 'returned']; return [] }
